#include <bits/stdc++.h>
using namespace std;

const int N = 12;
const int INF = 1000000009;
const int dx[4] = {0, 1, 0, -1};
const int dy[4] = {1, 0, -1, 0};

int n, t;
char a[N][N], b[N][N];
int sx, sy;
int dist[N][N];

struct Cell {
    int x, y;
    Cell() {}
    Cell(int x, int y) : x(x), y(y) {}
};

void computeDist(int startX, int startY) {
    for (int i = 0; i < n; ++i)
        memset(dist[i], 0x3f, sizeof(dist[i]));
    bool seen[N][N] = {};
    queue<Cell> q;
    seen[startX][startY] = true;
    dist[startX][startY] = 0;
    q.push(Cell(startX, startY));
    while (!q.empty()) {
        Cell cur = q.front(); q.pop();
        for (int k = 0; k < 4; ++k) {
            int nx = cur.x + dx[k], ny = cur.y + dy[k];
            if (nx >= 0 && nx < n && ny >= 0 && ny < n && !seen[nx][ny] && isdigit(a[nx][ny])) {
                seen[nx][ny] = true;
                dist[nx][ny] = dist[cur.x][cur.y] + 1;
                q.push(Cell(nx, ny));
            }
        }
    }
}

bool dp[72][N][N][N][N];
bool reachable[N][N][N][N];
int cap[2 * N * N + 2][2 * N * N + 2];
int parent[2 * N * N + 2];
bool visited[2 * N * N + 2];

bool findPath() {
    memset(visited, false, sizeof(visited));
    memset(parent, 0, sizeof(parent));
    queue<int> q;
    visited[0] = true;
    q.push(0);
    while (!q.empty()) {
        int v = q.front(); q.pop();
        if (v == 2 * n * n + 1) return true;
        for (int u = 0; u <= 2 * n * n + 1; ++u) {
            if (cap[v][u] > 0 && !visited[u]) {
                visited[u] = true;
                parent[u] = v;
                q.push(u);
            }
        }
    }
    return false;
}

void solve() {
    scanf("%d%d", &n, &t);
    for (int i = 0; i < n; ++i) scanf(" %s", a[i]);
    for (int i = 0; i < n; ++i) scanf(" %s", b[i]);
    scanf("%d%d", &sx, &sy);
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (a[i][j] == 'Z') { sx = i; sy = j; }
    computeDist(sx, sy);

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (isdigit(a[i][j]))
                dp[0][i][j][i][j] = true;

    for (int time = 0; time < t; ++time) {
        for (int s1 = 0; s1 < n; ++s1)
            for (int s2 = 0; s2 < n; ++s2)
                for (int x = 0; x < n; ++x)
                    for (int y = 0; y < n; ++y) {
                        if (!dp[time][s1][s2][x][y]) continue;
                        if (dist[x][y] <= time) continue;
                        for (int k = 0; k < 4; ++k) {
                            int nx = x + dx[k], ny = y + dy[k];
                            if (nx >= 0 && nx < n && ny >= 0 && ny < n && isdigit(a[nx][ny]) && dist[nx][ny] >= time + 1)
                                dp[time + 1][s1][s2][nx][ny] = true;
                        }
                    }
    }

    for (int time = 0; time <= t; ++time)
        for (int s1 = 0; s1 < n; ++s1)
            for (int s2 = 0; s2 < n; ++s2)
                for (int x = 0; x < n; ++x)
                    for (int y = 0; y < n; ++y)
                        if (dp[time][s1][s2][x][y])
                            reachable[s1][s2][x][y] = true;

    memset(cap, 0, sizeof(cap));
    for (int x = 0; x < n; ++x)
        for (int y = 0; y < n; ++y)
            if (isdigit(a[x][y]))
                cap[0][x * n + y + 1] = a[x][y] - '0';

    for (int x = 0; x < n; ++x)
        for (int y = 0; y < n; ++y)
            if (isdigit(b[x][y]))
                cap[n * n + x * n + y + 1][2 * n * n + 1] = b[x][y] - '0';

    for (int x1 = 0; x1 < n; ++x1)
        for (int y1 = 0; y1 < n; ++y1)
            if (isdigit(a[x1][y1]))
                for (int x2 = 0; x2 < n; ++x2)
                    for (int y2 = 0; y2 < n; ++y2)
                        if (isdigit(a[x2][y2]) && reachable[x1][y1][x2][y2])
                            cap[x1 * n + y1 + 1][n * n + x2 * n + y2 + 1] = INF;

    while (findPath()) {
        int flow = INF;
        for (int v = 2 * n * n + 1; v; v = parent[v])
            flow = min(flow, cap[parent[v]][v]);
        for (int v = 2 * n * n + 1; v; v = parent[v]) {
            cap[parent[v]][v] -= flow;
            cap[v][parent[v]] += flow;
        }
    }

    int ans = 0;
    for (int i = 0; i <= 2 * n * n + 1; ++i)
        ans += cap[i][0];
    printf("%d\n", ans);
}

int main() {
    solve();
    return 0;
}
